{
  "PageTitle": "How It Works",
  "PageLead": "From a natural-language brief to a Project Analysis plan, per-module DBML, generated microservices, GitHub repositories, and Cloud Run deployments — step by step.",
  "ShowNumbers": false,
  "Items": [
    {
      "Section": "Get started",
      "Title": [
        "Describe your business requirements to AI"
      ],
      "Body": [
        "Start on the homepage with Try generating with AI, or open QuickCode Studio and choose Project with AI. Describe your product in natural language (optionally attach a PDF). Pick Google Gemini, OpenAI, or Anthropic Claude. QuickCode runs a Project Analysis first — a module plan you can review — then generates DBML per module."
      ],
      "ItemType": "MainPage",
      "SubItems": [
        {
          "Type": "IconType2",
          "Items": [
            {
              "Title": [
                "Google Gemini"
              ],
              "ImageUrl": "~/img/icons/gemini_icon.png",
              "DarkUrl": "~/img/icons/gemini_icon_dark.png"
            },
            {
              "Title": [
                "OpenAI"
              ],
              "ImageUrl": "~/img/icons/openai_icon.png",
              "DarkUrl": "~/img/icons/openai_icon_dark.png"
            },
            {
              "Title": [
                "Anthropic Claude"
              ],
              "ImageUrl": "~/img/icons/anthropic_icon.png",
              "DarkUrl": "~/img/icons/anthropic_icon_dark.png"
            }
          ]
        },
        {
          "Type": "Text",
          "Items": [
            {
              "Title": [
                "Do not generate Identity/User modules"
              ],
              "Body": [
                "QuickCode injects IdentityModule automatically. Do not add separate user, role, or auth modules in AI output or DBML, they conflict with the built-in module."
              ]
            },
            {
              "Title": [
                "Platform modules from the catalog"
              ],
              "Body": [
                "When email, SMS, or similar capabilities fit, analysis can select ready-made PLATFORM modules from the QuickCode catalog instead of inventing duplicate services."
              ]
            }
          ]
        }
      ],
      "ImagesOptions": {
        "DisplaySize": "thumb",
        "PreviewSize": "big",
        "MultiSize": "full",
        "MultiLayout": "carousel"
      },
      "Images": [
        {
          "Url": "~/img/screenshots/big/quickcode-studio-add-project-ai-light.jpg",
          "DarkUrl": "~/img/screenshots/big/quickcode-studio-add-project-ai-dark.jpg",
          "Alt": "Project with AI in QuickCode Studio",
          "Caption": "Project with AI"
